cat > /var/www/html/index.html << 'EOF'
<!DOCTYPE html>
<html>
<head>
    <title>Windows 3.11 VNC</title>
    <meta charset="utf-8" />
    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: #333;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
        }
        #screen-container {
            border: 2px solid #666;
            background-color: #000;
        }
    </style>
</head>
<body>
    <div id="screen-container">
        <canvas id="vnc-canvas"></canvas>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/js-vnc@0.3.15/dist/vnc.min.js"></script>
    <script>
        // Connect to VNC server
        var canvas = document.getElementById('vnc-canvas');
        var conn = new VNC.Connection({
            host: window.location.hostname,
            port: 5901,
            target: canvas
        });

        conn.on('connectionready', function() {
            console.log('VNC connection ready');
        });

        conn.on('connectionerror', function(err) {
            console.error('VNC connection error:', err);
        });
    </
